\title{Quotient Orbit Compression: A Unified Bounded-Horizon Collision
Principle for Coarse-Grained Deterministic Dynamics}
\author{Aristotle}
\date{2026-06-22}

\begin{document}
\maketitle

\begin{abstract}
We develop and rigorously establish a single combinatorial principle that
governs deterministic dynamics observed through a coarse, finite lens, and we
show that it simultaneously answers three superficially distinct questions:
\emph{when must a coarse-grained trajectory recur?}, \emph{when is a collision
in an iterated function guaranteed?}, and \emph{how large can an observable
state log become?} Let $\alpha$ be a finite set of microscopic states, let
$f : \alpha \to \alpha$ be an arbitrary deterministic transition map, and let
$\rho$ be an equivalence relation (a \emph{setoid}) on $\alpha$ whose quotient
$\alpha/\rho$ has cardinality $k$. Our central theorem
(\code{exists\_iterate\_rel\_of\_card\_quotient}) asserts that from \textbf{any}
start $x$ there exist times $0 \le m < n \le k$ with
$f^{[m]}(x) \sim_\rho f^{[n]}(x)$: a coarse collision is forced within $k$ steps,
independent of $|\alpha|$ and of the structure of $f$. We prove this via a
pigeonhole argument on the quotient trace
(\code{exists\_lt\_lt\_iterate\_quotient\_eq}) combined with a soundness bridge
from label-equality to genuine indistinguishability
(\code{quotient\_eq\_implies\_rel}). We then derive an observable-orbit ceiling
(\code{eml\_observable\_orbit\_bound}), define and bound natural compression
statistics --- collision entropy, compression ratio
(\code{orbitCompressionRatio\_le\_one}), and observable diameter --- and
interpret the result as a cryptographic collision certificate and a
certified-robustness guarantee. We show the horizon $k$ is tight via an explicit
single-cycle construction. All results are constructive and have been formally
verified.
\end{abstract}

\section{Introduction}

\subsection{Motivation}
Deterministic processes on finite state spaces are everywhere: cellular
automata, hash-function iterations, finite-precision numerical integrators,
register machines, and discrete dynamical models of physical systems. In almost
all practical settings we do not observe the full microscopic state; we observe
a \emph{coarse-graining}: a temperature band rather than a molecular
configuration, a digest rather than a preimage, a logged category rather than a
raw sensor reading.

A coarse-graining is precisely an equivalence relation $\rho$ on the state set
$\alpha$, and the \emph{observable} state space is the quotient $\alpha/\rho$.
The fundamental question is: what can we guarantee about the observable
trajectory, knowing nothing about the microscopic map beyond the fact that it is
a deterministic self-map of a finite set? We isolate and prove the strongest
guarantee that depends only on the resolution $k = |\alpha/\rho|$, and show it
unifies three traditions: algebraic dynamics (finite quotient recurrence),
cryptography (worst-case collision certificates), and observable-state
compression (hard ceilings on logged summaries).

\subsection{Contributions}
\begin{itemize}
  \item A soundness bridge (Theorem~\ref{thm:bridge}) from quotient
  label-equality to the underlying setoid relation.
  \item The pigeonhole core (Theorem~\ref{thm:pigeon}): $k+1$ observations into
  $k$ classes force a repeated class.
  \item The central bounded-horizon collision theorem
  (Theorem~\ref{thm:main}): a coarse collision within $k$ steps, for any $f$
  and any start.
  \item Observable-orbit definitions and the ceiling theorem
  (Theorem~\ref{thm:ceiling}).
  \item Compression statistics with proven bounds (Theorems~\ref{thm:entropy}
  and~\ref{thm:ratio}).
  \item Cryptographic and certified-robustness readings.
  \item A tightness construction (Theorem~\ref{thm:tight}).
\end{itemize}

\section{Preliminaries and Notation}
Throughout, $\alpha$ is a finite type with decidable equality, and
$|\alpha| = \mathrm{card}(\alpha)$.

\paragraph{Iteration.} For $f : \alpha \to \alpha$ and $n \in \NN$, the
$n$-fold iterate $f^{[n]}$ is defined by $f^{[0]} = \mathrm{id}$ and
$f^{[n+1]} = f \circ f^{[n]}$. The trajectory from $x$ is
$(f^{[n]}(x))_{n \ge 0}$.

\paragraph{Setoid / coarse lens.} A \emph{setoid} $\rho$ on $\alpha$ is a
decidable equivalence relation; we write $a \sim_\rho b$ for its relation. The
\emph{quotient} $\alpha/\rho$ is the set of classes, with class map
$\cls{(\cdot)} : \alpha \to \alpha/\rho$, $\cls{a} = [a]_\rho$. We set
$k := |\alpha/\rho|$ for the \emph{resolution}. Since the class map is
surjective, $k \le |\alpha|$, and $\cls{a} = \cls{b}$ holds iff
$a \sim_\rho b$.

\section{The Soundness Bridge}

\begin{theorem}[\code{quotient\_eq\_implies\_rel}]\label{thm:bridge}
For any setoid $\rho$ on $\alpha$ and any $a,b \in \alpha$,
\[
  \cls{a} = \cls{b} \;\Longrightarrow\; a \sim_\rho b.
\]
\end{theorem}

\begin{proof}[Proof sketch]
Equality of quotient classes is, by the universal property of the quotient,
exactly the statement that the two representatives are identified by $\rho$.
Extracting a witness of the relation from an equality of classes is the standard
quotient exactness principle.
\end{proof}

This lemma guarantees that every collision detected through the lens (an equality
of labels) is a real collision (an honest $\rho$-relation).

\section{The Bounded-Horizon Collision Theorem}

\begin{theorem}[\code{exists\_lt\_lt\_iterate\_quotient\_eq}]\label{thm:pigeon}
Let $\alpha$ be finite, $\rho$ a decidable setoid with $k = |\alpha/\rho|$,
$f : \alpha \to \alpha$, and $x \in \alpha$. Then there exist $m,n \in \NN$ with
\[
  m < n, \qquad n \le k, \qquad \cls{f^{[m]}(x)} = \cls{f^{[n]}(x)}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
Consider $g : \{0,\dots,k\} \to \alpha/\rho$, $g(i) = \cls{f^{[i]}(x)}$, whose
domain has $k+1$ elements and codomain has $k$. Since $k < k+1$, the finite
pigeonhole principle gives $i \ne j$ with $g(i) = g(j)$. Relabel so $i < j$ and
set $m = i$, $n = j$; both lie in $\{0,\dots,k\}$, so $n \le k$.
\end{proof}

\begin{theorem}[\code{exists\_iterate\_rel\_of\_card\_quotient}]\label{thm:main}
Let $\alpha$ be finite, $\rho$ a decidable setoid with $k = |\alpha/\rho|$,
$f : \alpha \to \alpha$, and $x \in \alpha$. Then there exist $m,n \in \NN$ with
\[
  0 \le m < n \le k \qquad\text{and}\qquad f^{[m]}(x) \sim_\rho f^{[n]}(x).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Apply Theorem~\ref{thm:pigeon} to obtain $m < n \le k$ with
$\cls{f^{[m]}(x)} = \cls{f^{[n]}(x)}$, then apply Theorem~\ref{thm:bridge} to
upgrade the label equality to the relation.
\end{proof}

\begin{remark}
A deterministic process observed through a $k$-class lens is guaranteed to
revisit an observable class within $k$ steps, from any start, regardless of
$|\alpha|$ and of the structure of $f$. As an algorithm, $O(k)$ observations
suffice to detect a coarse collision (store $k+1$ labels, report the first
repeat).
\end{remark}

\section{Observable Orbits and the Compression Ceiling}

\begin{definition}[observable structures]
Fix $\alpha$ finite, $\rho$ decidable, $f$, $x$, and a horizon $N \in \NN$.
\begin{itemize}
  \item The \emph{quotient-observable trace}
  $\mathrm{trace}_N(i) = \cls{f^{[i]}(x)}$ for $0 \le i \le N$
  (\code{quotientObservableTrace}).
  \item The \emph{observable orbit set}
  $\Orb_N = \{\cls{f^{[i]}(x)} : 0 \le i \le N\} \subseteq \alpha/\rho$
  (\code{observableOrbitSet}).
  \item The \emph{observable orbit count} $|\Orb_N|$
  (\code{observableOrbitCount}).
  \item The \emph{observable diameter} $|\Orb_N| - 1$
  (\code{quotientObservableDiameter}).
\end{itemize}
\end{definition}

\begin{theorem}[\code{eml\_observable\_orbit\_bound}]\label{thm:ceiling}
For all $N$, $\;|\Orb_N| \le k.$
\end{theorem}

\begin{proof}[Proof sketch]
$\Orb_N$ is a subset of the finite set $\alpha/\rho$, so its cardinality is at
most $|\alpha/\rho| = k$.
\end{proof}

\begin{corollary}[\code{eml\_observable\_orbit\_bound\_at\_quotient\_card}]
Specializing $N = k$ gives $|\Orb_k| \le k$.
\end{corollary}

\begin{corollary}[\code{quotientObservableDiameter\_bound}]
The observable diameter satisfies $(|\Orb_N| - 1) + 1 \le k + 1$.
\end{corollary}

\section{Compression Statistics}

\begin{definition}
The \emph{collision entropy} is $H_\rho = |\alpha| - k$
(\code{quotientCollisionEntropy}); the \emph{orbit compression ratio} is
$R_\rho = k/|\alpha|$ (\code{orbitCompressionRatio}); the \emph{compression gap}
between collision indices $m < n$ is $n - m$ (\code{quotientCompressionGap}).
\end{definition}

\begin{theorem}[\code{quotientCollisionEntropy\_nonneg}]\label{thm:entropy}
$H_\rho \ge 0$.
\end{theorem}

\begin{proof}[Proof sketch]
Surjectivity of the class map gives $k \le |\alpha|$, so $|\alpha| - k \ge 0$.
\end{proof}

\begin{theorem}[\code{orbitCompressionRatio\_le\_one}]\label{thm:ratio}
$R_\rho \le 1$.
\end{theorem}

\begin{proof}[Proof sketch]
Surjectivity of the class map gives $k \le |\alpha|$; dividing by the
nonnegative denominator $|\alpha|$ yields $k/|\alpha| \le 1$.
\end{proof}

\section{Tightness of the Horizon}

\begin{theorem}[tightness]\label{thm:tight}
For every $k \ge 1$ there exist a finite set $\alpha$, a setoid $\rho$ with
$|\alpha/\rho| = k$, a map $f$, and a start $x$ such that the first coarse
collision occurs exactly at index $n = k$.
\end{theorem}

\begin{proof}[Proof sketch]
Take $\alpha = \ZZ/k\ZZ$, $\rho$ equality, $f(a) = a + 1 \bmod k$, and $x = 0$.
The trajectory $0,1,\dots,k-1,0,\dots$ visits $k$ distinct classes before its
first repeat at step $k$, where $f^{[0]}(0) = f^{[k]}(0) = 0$.
\end{proof}

\section{The Three Bridges}

\paragraph{Algebraic dynamics.} Theorem~\ref{thm:main} is a constructive,
worst-case recurrence theorem requiring no invariant measure --- only
finiteness and determinism --- and yielding explicit witnesses.

\paragraph{Cryptography.} Reading $f$ as an iterated function and $\rho$ as
``same observable digest,'' a $\rho$-related pair is a collision, and
Theorem~\ref{thm:main} certifies one within $k$ iterations: the rigorous
backbone of birthday-bound and Pollard-$\rho$ search
(\code{lattice\_crypto\_collision\_certificate},
\code{post\_quantum\_security\_collision\_upper\_bound}).

\paragraph{Compression and robustness.} Theorem~\ref{thm:ceiling} gives an
$O(k)$ ceiling on observable state complexity; bundled with recurrence it
yields \code{certified\_robustness\_via\_quotient\_compression}: bounded and
recurrent observables with checkable certificates.

\section{Algorithms}
\textbf{A: hash-set collision detection.} Store first-seen times of class
labels; on the first repeat return $(m,n)$. Loop runs $\le k+1$ times;
$O(k)$ time and space.\\
\textbf{B: Floyd constant-space cycle detection.} Two pointers over the label
sequence; $O(k)$ time, $O(1)$ extra space; correctness from eventual
periodicity (Theorem~\ref{thm:main}).\\
\textbf{C: compression auditing.} Compute $k$, then $H_\rho$ and $R_\rho$;
Theorems~\ref{thm:entropy} and~\ref{thm:ratio} certify the bounds.

\section{Discussion and Future Work}
The theory assumes only finiteness, determinism, and a decidable lens; its
total independence from the structure of $f$ is both its strength and its
boundary. It bounds the first coarse collision and the observable orbit size,
but average-case ($\Theta(\sqrt{k})$) statements require probabilistic models of
$f$. The horizon $k$ is tight (Theorem~\ref{thm:tight}). Future work:
average-case refinement recovering the birthday law as an envelope; quantitative
entropy of the label process; product/skew systems; and verified constant-space
certificate generation.

\section{Conclusion}
A single pigeonhole argument, made honest by a quotient-soundness bridge, yields
a sharp, universal law: a deterministic process observed through a $k$-class lens
must repeat an observable class within $k$ steps, and its entire observable log
lives in a space of size at most $k$. The horizon is tight, the statistics are
bounded, and the same theorem is a recurrence law, a collision certificate, and
a compression ceiling at once.

\end{document}

